INSERT INTO `creature_text` (`entry`,`groupid`,`id`,`text`,`type`,`language`,`probability`,`emote`,`duration`,`sound`,`comment`) VALUES
(56589,0,0,'Keep those archers off the wall. Raigonn must reach the gate.',14,0,0.0,0,0,29377,'boss_striker_gadok'),
(56589,1,0,'I\'ll hurl your corpses from this tower.',14,0,0.0,0,0,29375,'boss_striker_gadok'),
(56589,2,0,'Our numbers... endless! You... cannot win...',14,0,0.0,0,0,29376,'boss_striker_gadok'),
(56589,3,0,'You joined a battle already lost.',14,0,0.0,0,0,29378,'boss_striker_gadok'),
(56589,3,1,'Air superiority.',14,0,0.0,0,0,29379,'boss_striker_gadok'),
(56589,3,2,'As expected.',14,0,0.0,0,0,29380,'boss_striker_gadok'),
(56636,0,0,'There will be no escaping me.',14,0,0.0,0,0,29074,'boss_commander_rimok'),
(56636,1,0,'Empress... forgive me!',14,0,0.0,0,0,29075,'boss_commander_rimok'),
(56636,2,0,'The gates are about to fall. Quickly! Slaughter these meddlers!',14,0,0.0,0,0,29076,'boss_commander_rimok'),
(56636,3,0,'Hahahahaha!',14,0,0.0,0,0,26321,'boss_commander_rimok'),
(56636,3,1,'This wall is your grave!',14,0,0.0,0,0,29078,'boss_commander_rimok'),
(56636,3,2,'None may stand against us!',14,0,0.0,0,0,29079,'boss_commander_rimok'),
(56742,0,0,'We\'ve got to light that signal fire. Without reinforcements, they\'ll destroy the gate!',12,0,0.0,5,0,29068,'Serpent\'s Spine Defender'),
(56743,0,0,'But the mantid have overrun the area. There\'s no clear path!',12,0,0.0,1,0,29071,'Serpent\'s Spine Defender'),
(56745,0,0,'Don\'t worry! I can make it!',12,0,0.0,0,0,27692,'Serpent\'s Spine Trainee'),
(56877,0,0,'%s\'s |cFFFF0000Weak Spot|r is exposed! Attack it to break his Impervious Carapace!',41,0,100.0,0,0,0,'boss_raigonn'),
(56877,1,0,'The |cFFFE9A2EKrik\'thik Swarm Bringer|r reinforcements join the battle!',41,0,100.0,0,0,0,'boss_raigonn'),
(56877,2,0,'The |cFFFE9A2EKrik\'thik Engulfer|r reinforcements appear above!',41,0,100.0,0,0,0,'boss_raigonn'),
(56877,3,0,'The |cFFFE9A2EKrik\'thik Protectorate|r reinforcements appear!',41,0,100.0,0,0,0,'boss_raigonn'),
(56906,0,0,'Gate?! I\'m going to bring this whole wall down!',14,0,0.0,0,0,29341,'boss_saboteur_kiptilak - SAY_INTRO'),
(56906,1,0,'I brought enough bombs... for all of you!',14,0,0.0,0,0,29339,'boss_saboteur_kiptilak - SAY_AGGRO'),
(56906,2,0,'BOOM shakalaka!',14,0,0.0,0,0,29342,'boss_saboteur_kiptilak - SAY_SLAY'),
(56906,2,1,'I\'m the bomber man...tid!',14,0,0.0,0,0,29343,'boss_saboteur_kiptilak - SAY_SLAY'),
(56906,2,2,'You blew it!',14,0,0.0,0,0,29344,'boss_saboteur_kiptilak - SAY_SLAY'),
(56906,3,0,'I... blew it...',14,0,0.0,0,0,29340,'boss_saboteur_kiptilak - SAY_DEATH'),
(56906,4,0,'You\'re the bomb!',14,0,0.0,0,0,29345,'boss_saboteur_kiptilak - SAY_SPECIAL'),
(56906,4,1,'This will be the bomb.',14,0,0.0,0,0,29346,'boss_saboteur_kiptilak - SAY_SPECIAL'),
(56906,4,2,'Things that make you go... BOOM!',14,0,0.0,0,0,29347,'boss_saboteur_kiptilak - SAY_SPECIAL'),
(56906,4,3,'BOOM! Explosion! Overpowering!',14,0,0.0,0,0,29348,'boss_saboteur_kiptilak - SAY_SPECIAL'),
(56906,4,4,'There goes the BOOM!',14,0,0.0,0,0,29349,'boss_saboteur_kiptilak - SAY_SPECIAL'),
(58202,0,0,'Help!',14,0,100.0,0,0,0,'Serpent\'s Spine Defender'),
(58202,0,1,'Mmmphhh',14,0,100.0,0,0,0,'Serpent\'s Spine Defender'),
(58202,0,2,'The mantid are coming over the wall!',14,0,100.0,0,0,0,'Serpent\'s Spine Defender');
